def sort_age(lst):
    for i in range(len(lst)-1):
        for j in range(i+1, len(lst)):
            if lst[i][1] < lst[j][1]:
                lst[i], lst[j] = lst[j], lst[i]
    return lst

def sort_age(lst):
    if lst == []:
        return []
    else:
        result = [lst[0]]
        for i in lst[1:]:
            if i[1] > result[0][1]:
                result.insert(0, i)
            elif i[1] < result[-1][1]:
                result.append(i)
            else:
                for j in range(len(result) - 1):
                    if i[1] < result[j][1] and i[1] > result[j+1][1]:
                        result.insert(j+1, i)
        return result

